import { pilotForPolitician } from '../data/kim-minseok-pilot.js';
import { jcsSupportConversion } from '../ui/cohort-metrics.js';

const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const TYPES=Object.freeze({assembly:{label:'국회의원',count:300},metropolitan:{label:'광역단체장',count:16},basic:{label:'기초단체장',count:227}});
const empty=()=>'<span class="info-empty" aria-label="추가 데이터 준비중"></span>';
const value=text=>text?esc(text):empty();

function photoMarkup(item,className='person-photo-placeholder',size=160){
  const photo=item?.photo,src=String(photo?.localPath||'');
  const initial=esc(String(item?.name||'?').slice(0,1));
  if(!src)return `<div class="${className} is-empty" data-politician-avatar><span class="politician-photo-initial" aria-hidden="true">${initial}</span></div>`;
  return `<div class="${className} has-photo" data-politician-avatar style="--photo-position:${esc(photo.focus||'50% 28%')}"><span class="politician-photo-initial" aria-hidden="true">${initial}</span><img data-politician-photo src="${esc(src)}" alt="" width="${size}" height="${size}" loading="lazy" decoding="async"></div>`;
}
function card(item){
  const type=TYPES[item.type]||TYPES.assembly,meta=[item.party,item.jurisdiction].filter(Boolean).join(' · '),short=item.type==='assembly'?(item.terms||item.committee):(item.office||item.roleLabel);
  return `<button type="button" class="person-slot-card data-connected now-category-card${item.isVacant?' is-vacant':''}" data-layout-route="/person/${esc(item.id)}" aria-label="${esc(item.name)} 상세페이지"><span class="slot-no now-category-card-rank">${item.isVacant?'공석':item.now?.categoryRank?`${item.now.categoryRank}위`:`SLOT ${String(item.slot).padStart(3,'0')}`}</span>${photoMarkup(item)}<span class="slot-lines"><b class="slot-data-name">${esc(item.name)}</b><span class="slot-data-meta">${esc(meta)}</span><span class="slot-data-short">${esc(short)}</span><span class="now-category-card-meta"><b>${item.now?`NOW ${item.now.score}`:'집계 준비 중'}</b><em>${item.now?`전체 ${item.now.rank}위 · ${esc(type.label)} ${item.now.categoryRank}위`:`${esc(type.label)} NOW 데이터 미반영`}</em></span></span></button>`;
}
export async function renderPoliticianDirectory(service,route='/now'){
  const query=new URLSearchParams(String(route).split('?')[1]||''),type=TYPES[query.get('type')]?query.get('type'):'assembly',offset=Math.max(0,Number(query.get('offset')||0)||0),limit=30;
  const result=await service.list(type,offset,limit),meta=TYPES[type];
  if(!result?.ok)return `<main class="subpage now-directory-page"><section class="page-hero"><span class="eyebrow">NOW RANK · CATEGORY LEAGUE</span><h1>NOW Rank · 분야별 순위</h1><p>정치인 DB 연결을 준비하고 있습니다.</p></section><section class="content-card"><div class="empty-state tall"><h2>정치인 데이터가 아직 이관되지 않았습니다</h2><p>${esc(result?.error||'POLITICIAN_DB_MISSING')}</p></div></section></main>`;
  const rows=Array.isArray(result.items)?result.items:[],total=Number(result.total||0),shownEnd=Math.min(total,offset+rows.length);
  const tabs=Object.entries(TYPES).map(([key,item])=>`<button type="button" class="${type===key?'active':''}" data-layout-route="/now?type=${key}"><b>${item.label}</b><span>${item.count}개 슬롯</span></button>`).join('');
  const pager=`<div class="politician-directory-pager">${offset>0?`<button class="ghost-btn" type="button" data-layout-route="/now?type=${type}&offset=${Math.max(0,offset-limit)}">이전 30명</button>`:''}<span>${total?`${offset+1}–${shownEnd} / ${total}`:'0명'}</span>${result.hasMore?`<button class="primary-btn" type="button" data-layout-route="/now?type=${type}&offset=${offset+limit}">다음 30명</button>`:''}</div>`;
  return `<main class="subpage now-directory-page"><section class="page-hero"><span class="eyebrow">NOW RANK · CATEGORY LEAGUE</span><h1>NOW Rank · 분야별 순위</h1><p>메인 TOP10은 전체 정치인 통합 순위입니다. 전체보기에서는 국회의원·광역단체장·기초단체장별로 같은 NOW 점수를 다시 정렬해 각 분야의 독립 순위를 보여줍니다</p><div class="capacity-line"><span>국회의원 300개 슬롯 · 광역단체장 16명 · 기초단체장 227명</span><b>현재 ${total}개 슬롯</b></div></section><nav class="now-category-tabs" aria-label="정치인 분류">${tabs}</nav><section class="content-card directory-section"><div class="section-title"><h2>${esc(meta.label)}</h2><span>${rows.length} / ${total}개 표시</span></div>${rows.length?`<div class="person-grid now-category-card-grid">${rows.map(card).join('')}</div>`:'<div class="empty-state"><h2>등록된 정치인 프로필이 없습니다</h2></div>'}${pager}</section></main>`;
}
function basicInfo(item){return `<dl class="info-list"><div><dt>이름</dt><dd>${value(item.name)}</dd></div><div><dt>현재 직책</dt><dd>${value(item.office||item.roleLabel)}</dd></div><div><dt>정당</dt><dd>${value(item.party)}</dd></div><div><dt>${esc(item.jurisdictionLabel||'지역')}</dt><dd>${value(item.jurisdiction)}</dd></div><div><dt>구분</dt><dd>${value(item.terms)}</dd></div><div><dt>사진</dt><dd>${item.photo?.localPath?'프로필 사진 연결':'등록된 사진 없음'}</dd></div></dl>`;}
function electionInfo(item){const term=item.termStart||item.termEnd?`${item.termStart||'—'} ~ ${item.termEnd||'—'}`:'';return `<dl class="info-list"><div><dt>현 임기</dt><dd>${value(term)}</dd></div><div><dt>${item.type==='assembly'?'선수':'민선'}</dt><dd>${value(item.terms)}</dd></div><div><dt>최근 선거</dt><dd>${value(item.electionLabel)}</dd></div><div><dt>정당</dt><dd>${value(item.party)}</dd></div><div><dt>${item.type==='assembly'?'소속 위원회':'관할 지역'}</dt><dd>${value(item.type==='assembly'?item.committee:item.jurisdiction)}</dd></div></dl>`;}
function timeline(item){const rows=[];if(item.electionLabel)rows.push([item.type==='assembly'?'2024':'2026',item.electionLabel,item.jurisdiction]);if(item.type==='assembly'&&item.terms)rows.push(['현재',item.terms,'국회의원 당선 횟수 기준']);if(item.type==='assembly'&&item.committee)rows.push(['현재',item.committee,'국회 공개정보 기반']);if(item.type!=='assembly')rows.push(['2026.07.01','민선 9기 임기 시작',item.office||item.roleLabel]);return rows.map(([year,title,sub])=>`<div class="timeline-row live"><span class="timeline-year">${esc(year)}</span><div class="timeline-copy"><b>${esc(title)}</b><span>${esc(sub)}</span></div></div>`).join('')||'<div class="timeline-row"><span class="timeline-year"></span><div class="timeline-copy"><i></i><i></i></div></div>';}
const pending=()=>'<span class="politician-data-pending">데이터 준비 중</span>';
const sectionTitle=(en,ko,note='데이터 연결 전')=>`<div class="section-title person-analysis-title"><div><span class="eyebrow">${esc(en)}</span><h2>${esc(ko)}</h2></div><span>${esc(note)}</span></div>`;
const clamp=value=>Math.max(0,Math.min(100,Number(value)||0));
const hasMetric=value=>value!==null&&value!==undefined&&value!==''&&Number.isFinite(Number(value));
const polarPoint=(index,total,radius,cx=110,cy=110)=>{const angle=(-Math.PI/2)+(Math.PI*2*index/total);return `${(cx+Math.cos(angle)*radius).toFixed(1)},${(cy+Math.sin(angle)*radius).toFixed(1)}`;};
const radarPoints=(items,radius=82)=>items.map((item,index)=>polarPoint(index,items.length,radius*(clamp(item.score)/100))).join(' ');
const radarFrame=(total,radius)=>Array.from({length:total},(_,index)=>polarPoint(index,total,radius)).join(' ');
function radarVisual(items,className,label){
  const axes=items.map((_,index)=>`<line x1="110" y1="110" x2="${polarPoint(index,items.length,82).split(',')[0]}" y2="${polarPoint(index,items.length,82).split(',')[1]}"></line>`).join('');
  const hasValues=items.some(item=>hasMetric(item.score));
  const labels=items.map((item,index)=>{const angle=(-Math.PI/2)+(Math.PI*2*index/items.length),x=110+Math.cos(angle)*104,y=110+Math.sin(angle)*104,anchor=Math.cos(angle)>.25?'start':Math.cos(angle)<-.25?'end':'middle';return `<text class="radar-axis-label" x="${x.toFixed(1)}" y="${(y+4).toFixed(1)}" text-anchor="${anchor}">${esc(item.label)}${hasMetric(item.score)?` ${item.score}`:''}</text>`;}).join('');
  return `<div class="${className}${hasValues?'':' is-pending'}"><svg viewBox="-24 -24 268 268" role="img" aria-label="${esc(label)}"><polygon class="radar-grid radar-grid-outer" points="${radarFrame(items.length,82)}"></polygon><polygon class="radar-grid" points="${radarFrame(items.length,61.5)}"></polygon><polygon class="radar-grid" points="${radarFrame(items.length,41)}"></polygon>${axes}${hasValues?`<polygon class="radar-value" points="${radarPoints(items)}"></polygon>${items.map((item,index)=>{const angle=(-Math.PI/2)+(Math.PI*2*index/items.length),radius=82*(clamp(item.score)/100);return `<circle cx="${(110+Math.cos(angle)*radius).toFixed(1)}" cy="${(110+Math.sin(angle)*radius).toFixed(1)}" r="4"></circle>`;}).join('')}`:''}${labels}</svg></div>`;
}
function bulletLedger(items,className='person-core-bullet-ledger'){
  return `<div class="${className}">${items.map(item=>`<article><div><b>${esc(item.label)}</b><small>${esc(item.desc||item.note||'데이터 연결 후 표시')}</small></div><span class="jcs-bullet-track"><i></i><em style="width:${hasMetric(item.score)?clamp(item.score):0}%"></em></span><strong>${hasMetric(item.score)?item.score:'—'}</strong></article>`).join('')}</div>`;
}
function activityBars(title,index,items){
  return `<section class="person-activity-bar-panel"><header><span>${String(index).padStart(2,'0')}</span><h3>${esc(title)}</h3></header><div>${items.map(item=>`<article><div><b>${esc(item.label)}</b><strong>${hasMetric(item.score)?item.score:'—'}</strong></div><small>${esc(item.desc||'데이터 연결 후 표시')}</small><span class="jcs-category-bar"><i></i><em style="width:${hasMetric(item.score)?clamp(item.score):0}%"></em><b>기준 50</b></span><footer><span>${esc(item.left||'낮음')}</span><span>${esc(item.right||'높음')}</span></footer></article>`).join('')}</div></section>`;
}
function attentionFunnel(items){
  return `<div class="person-attention-funnel">${items.map((item,index)=>`<article style="--funnel-score:${hasMetric(item.score)?clamp(item.score):50}%"><span>0${index+1}</span><div><b>${esc(item.label)}</b><small>${esc(item.desc||'데이터 연결 후 표시')}</small></div><strong>${hasMetric(item.score)?item.score:'—'}</strong></article>`).join('')}</div>`;
}
const pendingCore=()=>['관심도','확산력','활동성','미디어성','지속성','변동성'].map(label=>({label,score:null,desc:'승인된 데이터 연결 후 표시'}));
const pendingActivity=labels=>labels.map(label=>({label,score:null,left:'낮음',right:'높음',desc:'승인된 데이터 연결 후 표시'}));
function publicAnalysisShell(){
  const core=pendingCore(),audience=pendingActivity(['관심 집중도','확장 가능성','반응 밀도','관심 안정성']),activity=pendingActivity(['활동 강도','현장성','정책 지향']),media=pendingActivity(['언론 노출','자발 확산','콘텐츠 반응']),transition=pendingActivity(['유입력','확장력','전환력','유지력']);
  return `<div class="person-analysis-report-page jcs-public-intelligence-v3" data-design-system="jcs-public-intelligence-v3"><section class="person-intelligence-cover"><div class="person-intelligence-cover-brand"><span>JCS POLITICAL INTELLIGENCE</span><b>PUBLIC BRIEF</b></div><div class="person-intelligence-cover-index"><small>NOW INDEX</small><strong>—</strong><span>NOW rank —</span></div><div class="person-intelligence-cover-copy"><span class="eyebrow">정참시 SIGNAL</span><h2>분석 데이터 연결 전</h2><p>공식 프로필을 유지하고 승인된 분석 데이터가 연결될 때만 지표를 표시합니다.</p></div><div class="person-intelligence-cover-status">${pending()}<span>PROFILE LAYOUT ACTIVE</span></div></section><section class="content-card person-intelligence-chapter">${sectionTitle('CORE INDICATORS','핵심 분석지표','6개 지표 · 값 미연결')}<div class="person-core-visual-v3">${radarVisual(core,'person-core-radar','핵심 분석지표 레이더 차트')}${bulletLedger(core)}</div></section><section class="content-card person-intelligence-chapter">${sectionTitle('AUDIENCE LANDSCAPE','관심 구조 분석','관심의 폭과 집중 구조')}<div class="person-audience-spectrum-v3 is-pending"><header><span>핵심층 집중</span><span>대중 확장</span></header><div><i></i><em style="left:50%"></em></div><strong>—</strong><p>관심 구조 판정은 승인된 데이터가 연결된 뒤 표시합니다.</p></div>${bulletLedger(audience,'person-audience-lollipops-v3')}</section><section class="content-card person-intelligence-chapter">${sectionTitle('ACTIVITY & MEDIA','활동·미디어 분석','행동과 노출 구조')}<div class="person-activity-bars">${activityBars('활동 구조',1,activity)}${activityBars('미디어 구조',2,media)}</div></section><section class="content-card person-intelligence-chapter">${sectionTitle('ATTENTION FLOW','관심 전이 분석','관심이 이동하는 방식')}${attentionFunnel(transition)}<div class="person-analysis-diagnosis is-pending"><span>정참시 종합진단</span><strong>데이터 준비 중</strong><p>개인별 판정값은 승인된 근거가 연결될 때만 표시합니다.</p></div></section></div>`;
}
function publicPilotAnalysis(data){
  return `<div class="person-analysis-report-page jcs-public-intelligence-v3" data-design-system="jcs-public-intelligence-v3"><section class="person-intelligence-cover"><div class="person-intelligence-cover-brand"><span>JCS POLITICAL INTELLIGENCE</span><b>PUBLIC BRIEF</b></div><div class="person-intelligence-cover-index"><small>NOW INDEX</small><strong>${data.signal.index}</strong><span>NOW rank ${data.rank.overall}</span></div><div class="person-intelligence-cover-copy"><span class="eyebrow">정참시 SIGNAL</span><h2>${esc(data.signal.label)}</h2><p>${esc(data.signal.summary)}</p></div><div class="person-intelligence-cover-status"><b>${esc(data.mode)}</b><span>${esc(data.snapshot)}</span></div></section><section class="content-card person-intelligence-chapter">${sectionTitle('CORE INDICATORS','핵심 분석지표','허용 원자료 기반 JCS 운영 지수')}<div class="person-core-visual-v3">${radarVisual(data.core,'person-core-radar',`${data.id==='assembly-001'?'김민석':'정치인'} 핵심 분석지표 레이더 차트`)}${bulletLedger(data.core)}</div></section><section class="content-card person-intelligence-chapter">${sectionTitle('AUDIENCE LANDSCAPE','관심 구조 분석','정당·경선·선거 맥락')}<div class="person-audience-spectrum-v3"><header><span>핵심층 집중</span><span>대중 확장</span></header><div><i></i><em style="left:${clamp(data.audience.position)}%"><b>${data.audience.position}</b></em></div><strong>${esc(data.audience.label)}</strong><p>${esc(data.audience.summary)}</p></div>${bulletLedger(data.audience.bars,'person-audience-lollipops-v3')}</section><section class="content-card person-intelligence-chapter">${sectionTitle('ACTIVITY & MEDIA','활동·미디어 분석','뉴스·공개 정치기록 기반')}<div class="person-activity-bars">${activityBars('활동 구조',1,data.activity)}${activityBars('미디어 구조',2,data.media)}</div><div class="person-visual-conclusion-v3"><b>활동과 노출의 격차</b><p>언론 노출 ${data.media[0].score}에 비해 현장성 ${data.activity[1].score}가 낮다. 대형 정치 일정 이후 생활 현장의 후속 증거를 연속 배치해야 한다.</p></div></section><section class="content-card person-intelligence-chapter">${sectionTitle('ATTENTION FLOW','관심 전이 분석','관심이 지지로 이동하는 방식')}${attentionFunnel(data.transition)}<div class="person-analysis-diagnosis"><span>정참시 종합진단</span><strong>${esc(data.diagnosis.title)}</strong><p>${esc(data.diagnosis.body)}</p></div></section></div>`;
}

const adminHead=(en,ko,note='데이터 연결 전')=>`<div class="admin-pi-section-head"><div><span>${esc(en)}</span><h3>${esc(ko)}</h3></div><small>${esc(note)}</small></div>`;
function adminGate({name,description,status,statusMeta}){return `<summary class="admin-intelligence-report-gate-v3"><span class="admin-intelligence-report-seal">JCS<small>PRIVATE</small></span><div class="admin-intelligence-report-title"><span>JCS ADMIN PRIVATE POLITICAL INTELLIGENCE</span><h2>${esc(name)} 정치 인텔리전스</h2><p>${esc(description)}</p></div><div class="admin-intelligence-report-meta"><small>REPORT STATUS</small><b>${esc(status)}</b><em>${esc(statusMeta)}</em><span class="admin-intelligence-report-open"><span class="closed-label">리포트 열기</span><span class="open-label">리포트 닫기</span><i>＋</i></span></div></summary>`;}
function adminExecutive({classification,title,body,evidenceValue,evidenceNote,kpis,pulseTitle,pulseValue,index}){return `<section class="admin-intelligence-executive-v3"><div class="admin-pi-classification"><span>PRIVATE · ADMIN ONLY</span><b>JCS POLITICAL INTELLIGENCE</b><em>${esc(classification)}</em></div><div class="admin-pi-executive-ribbon"><div><span class="eyebrow">EXECUTIVE INTELLIGENCE SUMMARY</span><h2>${esc(title)}</h2><p>${esc(body)}</p></div><div class="admin-pi-trust"><b>EVIDENCE MODE</b><strong>${esc(evidenceValue)}</strong><small>${esc(evidenceNote)}</small></div></div><div class="admin-pi-kpi-strip">${kpis.map(item=>`<article><small>${esc(item.label)}</small><strong>${esc(item.value)}</strong><span>${esc(item.note)}</span></article>`).join('')}</div><div class="admin-pi-diagnosis"><div><span>30D PULSE</span><small>최근 정치 신호</small></div><strong>${esc(pulseTitle)}</strong><em>${esc(pulseValue)}</em></div><div class="admin-pi-report-index">${index}</div></section>`;}
const adminBarRows=items=>`<div class="admin-support-bars-v3">${items.map(item=>`<article><header><b>${esc(item.label)}</b><strong>${Number.isFinite(Number(item.value))?item.value:'—'}</strong></header><small>${esc(item.note)}</small><span><i style="width:${Number.isFinite(Number(item.value))?clamp(item.value):0}%"></i></span></article>`).join('')}</div>`;
const sourceLedger=sources=>`<div class="admin-evidence-ledger-v3"><header><span>원자료</span><span>근거·적용 내용</span><span>상태</span></header>${sources.map(item=>`<article><b>${esc(item.type)}</b><div><a href="${esc(item.url||'#')}" target="_blank" rel="noopener">${esc(item.title)}</a><p>${esc(item.detail)}</p></div><span>${esc(item.grade)}</span></article>`).join('')}</div>`;
const cohortValue=(label,attention,data)=>{const support=jcsSupportConversion(data,attention),heat=(.08+(clamp(attention)/100)*.2).toFixed(2);return `<div class="admin-cohort-dual-value" style="--heat-opacity:${heat}"><b>${esc(label)}</b><span><small>관심</small><strong>${hasMetric(attention)?attention:'—'}</strong></span><span><small>지지전환</small><strong>${hasMetric(support)?support:'—'}</strong></span></div>`;};
const adminCohortRows=data=>`<div class="admin-cohort-definition jcs-analysis-compact"><b>연령·성별 관심·지지 전환 구조</b><span>관심지수와 JCS 지지전환지수</span></div>${(data.cohorts||[]).map(row=>`<article><h4>${esc(row.age)}<small>관심과 지지전환 분리</small></h4>${cohortValue('남성',row.male,data)}${cohortValue('여성',row.female,data)}</article>`).join('')}`;
